var waves=UnityEngine.Object.FindFirstObjectByType<DarkLord.Gameplay.WaveDirector>();waves.Tutorial.Advance(50);int n=0;while(waves.Tutorial.DialogueOpen&&n++<20)waves.Tutorial.NextDialogue();
void Move(UnityEngine.Vector3 p){waves.Lord.transform.position=p;waves.Lord.GetComponent<UnityEngine.Rigidbody2D>().position=p;UnityEngine.Physics2D.SyncTransforms();}
System.Collections.IEnumerator Capture(){yield return new UnityEngine.WaitForSecondsRealtime(.2f);UnityEngine.ScreenCapture.CaptureScreenshot("tmp/TutorialCorpseHighlight.png");yield return new UnityEngine.WaitForSecondsRealtime(.1f);var corpse=waves.Harvest.Corpses.First();Move(corpse.transform.position);waves.Harvest.TryInteract();yield return null;var summoning=waves.Lord.GetComponent<DarkLord.Player.MinionSummoning>();var facility=summoning.Dungeon.RecruitmentFacilities.Single();Move(facility.transform.position+UnityEngine.Vector3.down*4);yield return new UnityEngine.WaitForSecondsRealtime(.25f);UnityEngine.ScreenCapture.CaptureScreenshot("tmp/TutorialFacilityHighlight.png");yield return new UnityEngine.WaitForSecondsRealtime(.1f);Move(facility.transform.position+UnityEngine.Vector3.down);yield return null;yield return null;summoning.TryRecruit();yield return new UnityEngine.WaitForSecondsRealtime(.25f);UnityEngine.ScreenCapture.CaptureScreenshot("tmp/TutorialSummonButtonHighlight.png");}
waves.StartCoroutine(Capture());return "Capturing all three tutorial targets";
